    public void showWizard() {
        getWizardDialog();
        wizardPos = 0;
        updateCommands();
        getWizardDialog().setVisible(true);
    }
    
    protected void onPrevious() {
        if (cmdPrevWizard == null) return;
        if (wizardPos == 0) return;
        wizardPos--;
        updateCommands();
    }
    
    protected void onNext() {
        if (cmdPrevWizard == null) return;
        if (wizardPos == maxWizardPos) return;
        wizardPos++;
        updateCommands();
    }
    
    protected void updateCommands() {
        cmdPrevWizard.setEnabled(wizardPos > 0);
        cmdNextWizard.setVisible(wizardPos != maxWizardPos);
        cmdFinishWizard.setVisible(wizardPos == maxWizardPos);
        wizardTitleCardLayout.show(wizardTitleCardPanel, ""+wizardPos);
        wizardCardLayout.show(wizardCardPanel, ""+wizardPos);
        if (compsFocus[wizardPos] != null) compsFocus[wizardPos].requestFocus();
    }
    
